import{_ as e,o as d,c as o,ag as a}from"./chunks/framework.BoXUJ6sC.js";const h=JSON.parse('{"title":"도메인 자율 (권장 · 주의)","description":"","frontmatter":{},"headers":[],"relativePath":"kafka/domain-autonomy.md","filePath":"kafka/domain-autonomy.md"}'),r={name:"kafka/domain-autonomy.md"};function c(n,t,i,l,s,u){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="도메인-자율-권장-·-주의" tabindex="-1">도메인 자율 (권장 · 주의) <a class="header-anchor" href="#도메인-자율-권장-·-주의" aria-label="Permalink to &quot;도메인 자율 (권장 · 주의)&quot;">​</a></h1><h2 id="반드시-알아야-할-함정-어기면-조용히-틀어짐" tabindex="-1">반드시 알아야 할 함정 (어기면 조용히 틀어짐) <a class="header-anchor" href="#반드시-알아야-할-함정-어기면-조용히-틀어짐" aria-label="Permalink to &quot;반드시 알아야 할 함정 (어기면 조용히 틀어짐)&quot;">​</a></h2><ul><li><strong>같은 토픽 · 같은 그룹에 리스너 클래스를 둘 이상 두지 않습니다.</strong> 둘이면 파티션을 나눠 가져서 각 클래스가 메시지 일부만 받습니다. 에러는 나지 않습니다.</li><li><strong>리스너에서 예외를 잡아서 숨기지 않습니다.</strong> 숨기면 재시도도 DLT 이동도 일어나지 않습니다. <ul><li>예외: 자기 실패 보관이 있는 도메인(order의 <code>order_event_failure</code>, <code>payment_recovery</code>)은 보관에 성공하면 정상 반환하고, 보관에 실패하면 예외를 던집니다. 이 사실을 리스너 주석에 적습니다.</li></ul></li><li><strong>실패 보관이 리스너 트랜잭션에 합류하지 않게 합니다.</strong> 합류한 상태에서 예외를 삼키고 정상 반환하면 커밋할 때 <code>UnexpectedRollbackException</code>이 납니다(트랜잭션이 이미 rollback-only 상태입니다).</li><li><strong>같은 메시지가 두 번 올 수 있습니다.</strong> Kafka는 &quot;적어도 한 번&quot; 전달합니다. 같은 메시지를 두 번 받아도 결과가 1회분인지 테스트로 확인합니다.</li><li><strong>DLT로 빠진 메시지가 있으면 같은 키의 다음 메시지가 먼저 처리됩니다.</strong> 처리 전에 &quot;지금 상태에서 적용할 수 있는가&quot;를 확인합니다.</li><li><strong>같은 이벤트를 <code>@DomainEventListener</code>와 Kafka 양쪽에서 받지 않습니다.</strong></li></ul><h2 id="각-도메인이-정하는-것-권장-예시" tabindex="-1">각 도메인이 정하는 것 (권장 예시) <a class="header-anchor" href="#각-도메인이-정하는-것-권장-예시" aria-label="Permalink to &quot;각 도메인이 정하는 것 (권장 예시)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>권장 예시</th><th>비고</th></tr></thead><tbody><tr><td>보내는 방법</td><td>커밋 뒤 중계 빈(<code>@TransactionalEventListener(AFTER_COMMIT)</code> + <code>producer()</code> 확인). 실패하면 본문 없이 ERROR 로그</td><td>돈 · 재고처럼 이벤트를 잃으면 안 되는 흐름은 outbox를 발행 코드를 만들기 전에 검토합니다. 전송 작업은 한 번에 하나만 돌게 합니다(여러 개면 순서가 뒤집힙니다). 결제 · 상품 · 주문은 아웃박스, 회원 · 판매자 · 자녀는 전용 스레드 하나에서 커밋 뒤 바로 보냅니다</td></tr><tr><td>전송 대기 시간</td><td>앱 기본값(<code>max.block.ms</code> 60초)</td><td>브로커가 응답하지 않으면서 그 토픽 정보가 없을 때(앱 시작 직후 첫 전송, 5분 넘게 보내지 않은 토픽) <code>send()</code>가 이만큼 기다립니다. 커밋 뒤 요청 스레드에서 보내면 그 응답뿐 아니라, 같은 요청에서 커밋 뒤에 도는 다른 도메인의 <code>@DomainEventListener</code>도 함께 늦어집니다. 줄이고 싶으면 자기 템플릿에 짧은 값을 주는 정도면 충분합니다(지금 보내는 도메인은 전용 템플릿에서 3 ~ 5초로 둡니다). 아웃박스를 쓰면 릴레이가 따로 보내므로 요청 스레드가 기다리지 않습니다. 전용 스레드나 아웃박스는 필수가 아닙니다</td></tr><tr><td>리스너 모양</td><td>토픽마다 클래스 하나 + 안에서 <code>switch</code>로 종류를 나눔</td><td></td></tr><tr><td>트랜잭션 경계</td><td>처리 메서드에 <code>@Transactional</code></td><td><code>@KafkaListener</code>는 <code>@DomainEventListener</code>와 달리 새 트랜잭션을 열지 않습니다. 실패 보관이 있으면 처리를 자기 트랜잭션으로 분리합니다(주문이 이렇게 합니다)</td></tr><tr><td>재시도</td><td>처음 1번 + <code>FixedBackOff(1000L, 3)</code>. 다시 해도 같은 예외(<code>BusinessException</code>, <code>IllegalArgumentException</code>, <code>IllegalStateException</code>, NPE)는 바로 DLT</td><td>읽기 실패는 1절대로 재시도하지 않습니다</td></tr><tr><td>ack mode</td><td><code>RECORD</code></td><td></td></tr><tr><td>중복 처리</td><td>업무 상태 검사, UNIQUE 제약, <code>occurredAt</code> 비교, 처리 기록 표 중 선택</td><td></td></tr><tr><td>빈 List</td><td>옛 메시지에 없는 List는 빈 목록으로 다룹니다</td><td></td></tr></tbody></table>',5)])])}const _=e(r,[["render",c]]);export{h as __pageData,_ as default};
